function editBill(id){openBillForm(id)}
function printBill(id){let b=state.bills.find(x=>x.id===id);if(!b)return;let w=window.open('','_blank');if(!w){toast('Allow Pop-Ups To Print Or Save The Bill As PDF');return}let rows=b.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${safe(l.product)}<br><small>HSN ${safe(l.hsn||'—')} · Batch ${safe(l.batchNo||'—')} · ${safe(l.sku||'')}</small></td><td>${l.qty} ${safe(l.unit)}</td><td>${money(l.rate)}</td><td>${l.gstRate}%</td><td>${money(l.taxable??l.base)}</td><td>${money(l.taxAmount)}</td><td>${money(l.total)}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${safe(b.number)} · Vivid Drugs</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#182235;margin:0}.head{display:flex;justify-content:space-between;border-bottom:2px solid #079fc2;padding-bottom:16px}.head h1{margin:0 0 5px;font-size:25px;color:#079fc2}.head h2{margin:0 0 5px;font-size:20px}.muted{color:#657184;line-height:1.5}.tag{text-align:right;font-size:13px}.parties{display:flex;justify-content:space-between;margin:24px 0}.parties>div{width:47%}.parties h3{font-size:11px;color:#6d7988;text-transform:uppercase}.parties p{line-height:1.55}table{width:100%;border-collapse:collapse;margin-top:18px}th{background:#eef5f7;text-align:left;padding:9px;font-size:10px;text-transform:uppercase}td{border-bottom:1px solid #dfe5eb;padding:9px;vertical-align:top}small{color:#657184}.totals{width:300px;margin:20px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px}.grand{border-top:2px solid #16243a;font-size:16px;font-weight:bold;margin-top:5px;padding-top:12px!important}.foot{position:fixed;bottom:0;border-top:1px solid #ddd;width:100%;padding:8px 0;color:#667;font-size:10px}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="head"><div><h1>Vivid Drugs</h1><div class="muted">No 19, Lakshmipuram 2nd Street<br>Ariyamangalam, Trichy 620010<br>Contact: 87782 87266</div></div><div class="tag"><h2>INVOICE</h2><b>Invoice:</b> ${safe(b.number)}<br><b>Date:</b> ${safe(b.date)}</div></div><div class="parties"><div><h3>Bill To</h3><b>${safe(b.customer.name)}</b><p class="muted">${safe(b.customer.address)}<br>${safe(b.customer.phone)}<br>${safe(b.customer.email)}<br>${b.customer.gstin?"GSTIN: "+safe(b.customer.gstin):""}</p></div><div><h3>Payment Terms</h3><p>As Agreed</p></div></div><table><thead><tr><th>#</th><th>Description / HSN</th><th>Qty</th><th>Rate</th><th>GST</th><th>Taxable</th><th>GST Amt</th><th>Amount</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Subtotal</span><b>${money(b.subtotal)}</b></div><div><span>Discount (${b.discountPercent}%)</span><b>−${money(b.discountAmount)}</b></div><div><span>GST</span><b>${money(b.gstTotal)}</b></div><div class="grand"><span>Grand Total</span><span>${money(b.total)}</span></div></div><div class="foot">Thank You For Your Business · Vivid Drugs</div></body></html>`);w.document.close();setTimeout(()=>w.print(),300)}function editProduct(id){openForm('edit',id)}function editDelivery(id){openForm('delivery',id)}function editPurchase(id){openForm('purchase',id)}
async function removeProduct(id){let p=state.products.find(x=>x.id===id);if(!p||!confirm(`Delete ${p.name} And Its Current Batches? Past Bills And Transactions Remain In History.`))return;state.products=state.products.filter(x=>x.id!==id);state.batches=state.batches.filter(x=>x.productId!==id);await Promise.all(['products','batches'].map(save));render()}
async function removeRecord(key,id){let label=key==='suppliers'?'Supplier':'Customer';if(!confirm(`Delete This ${label}? Past Transactions And Bills Keep Their Saved Details.`))return;state[key]=state[key].filter(x=>x.id!==id);if(key==='customers'){for(let p of state.products)delete p.customerRates[id];await Promise.all(['customers','products'].map(save))}else await save(key);render()}
async function removeDelivery(id){let d=state.deliveries.find(x=>x.id===id);if(!d||!confirm(`Delete Delivery ${d.ref} And Return Its Stock To Inventory?`))return;if(d.allocations)restoreStock(d.productId,d.allocations);state.deliveries=state.deliveries.filter(x=>x.id!==id);await Promise.all(['products','batches','deliveries'].map(save));render()}
async function removePurchase(id){let p=state.purchases.find(x=>x.id===id),b=p&&state.batches.find(x=>x.id===p.batchId);if(!p)return;if(b&&Number(b.qty)<Number(p.qty)){toast('Some Of This Purchase Has Already Left Stock. Adjust Transactions First.');return}if(!confirm(`Delete Purchase ${p.ref} And Remove Its Quantity From Stock?`))return;if(b){b.qty-=Number(p.qty);syncProductQty(p.productId)}state.purchases=state.purchases.filter(x=>x.id!==id);await Promise.all(['products','batches','purchases'].map(save));render()}
async function removeBill(id){let bill=state.bills.find(x=>x.id===id);if(!bill||!confirm(`Delete Bill ${bill.number} And Return Its Stock To Inventory?`))return;for(let line of bill.lines)restoreStock(line.productId,line.allocations);state.bills=state.bills.filter(x=>x.id!==id);await Promise.all(['products','batches','bills'].map(save));render()}
const balanceOf=id=>{let a=state.bankAccounts.find(x=>x.id===id);return Number(a?.openingBalance||0)+state.ledgerEntries.reduce((n,x)=>n+(x.type==='transfer'?(x.toAccountId===id?Number(x.amount):x.accountId===id?-Number(x.amount):0):x.accountId===id?(x.type==='credit'?Number(x.amount):-Number(x.amount)):0),0)};
function accountStatementRows(id){let ordered=state.ledgerEntries.filter(x=>x.accountId===id||x.type==='transfer'&&x.toAccountId===id).sort((a,b)=>a.date.localeCompare(b.date)),balance=Number(state.bankAccounts.find(a=>a.id===id)?.openingBalance||0),rows=ordered.map(x=>{let incoming=x.type==='credit'||x.type==='transfer'&&x.toAccountId===id;balance+=incoming?Number(x.amount):-Number(x.amount);return {...x,runningBalance:balance,statementType:incoming?'credit':'debit',statementDescription:x.type==='transfer'?(incoming?'Transfer From '+(state.bankAccounts.find(a=>a.id===x.accountId)?.name||'Bank Account'):'Transfer To '+(state.bankAccounts.find(a=>a.id===x.toAccountId)?.name||'Bank Account')):x.description}});return rows.reverse().slice(0,12)}function ledgerPage(root){let entries=[...state.ledgerEntries].sort((a,b)=>b.date.localeCompare(a.date));root.innerHTML='<div class="heading"><div><h1>Ledger</h1><p>Create named ledgers, then select one when recording a bank voucher.</p></div><div class="actions"><button class="btn" onclick="createNamedLedger()">＋ Create Ledger</button><button class="btn" onclick="openBankTransfer()">⇄ Transfer Funds</button><button class="btn primary" onclick="openLedgerForm()" '+(state.bankAccounts.length?'':'disabled')+'>＋ Add Voucher</button></div></div><div class="cards">'+metric('Bank Accounts',state.bankAccounts.length,'Available Accounts','▣')+metric('Named Ledgers',state.ledgers.length,'Reusable Accounts','▤')+metric('Total Credits',money(state.ledgerEntries.filter(x=>x.type==='credit').reduce((n,x)=>n+Number(x.amount),0)),'Money In','＋')+metric('Total Debits',money(state.ledgerEntries.filter(x=>x.type==='debit').reduce((n,x)=>n+Number(x.amount),0)),'Money Out','−')+'</div><div class="panel" style="margin-bottom:16px"><div class="panel-head"><h2>Named Ledgers</h2></div><div class="table-wrap"><table><thead><tr><th>LEDGER NAME</th><th>VOUCHERS</th><th>ACTIONS</th></tr></thead><tbody>'+state.ledgers.map(l=>'<tr><td><b>'+safe(l.name)+'</b></td><td>'+state.ledgerEntries.filter(x=>x.ledgerId===l.id).length+'</td><td><button class="btn" onclick="renameNamedLedger(\''+l.id+'\')">Rename</button> <button class="row-actions" onclick="deleteNamedLedger(\''+l.id+'\')">Delete</button></td></tr>').join('')+'<tr><td colspan="3" class="empty">'+(state.ledgers.length?'':'No ledgers yet. Create one such as Wifi Bill.')+'</td></tr></tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Vouchers</h2></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>VOUCHER</th><th>LEDGER</th><th>BANK ACCOUNT</th><th>NARRATION</th><th>CREDIT</th><th>DEBIT</th><th>ACTIONS</th></tr></thead><tbody>'+entries.map(x=>'<tr><td>'+safe(x.date)+'</td><td>'+safe(x.voucherNo||'—')+'</td><td>'+safe(x.ledgerName||x.category||'Unassigned')+'</td><td>'+safe(x.accountName)+'</td><td>'+safe(x.description||'—')+'</td><td class="positive">'+(x.type==='credit'?money(x.amount):'—')+'</td><td class="negative">'+(x.type==='debit'?money(x.amount):'—')+'</td><td><button class="btn" onclick="openLedgerForm(\''+x.id+'\')">Edit</button> <button class="row-actions" onclick="removeLedgerEntry(\''+x.id+'\')">Delete</button></td></tr>').join('')+'<tr><td colspan="8" class="empty">'+(entries.length?'':'No vouchers recorded yet.')+'</td></tr></tbody></table></div></div>';let bankLedgerPanel=document.createElement('section');bankLedgerPanel.className='panel';let bankLedgerTitle=document.createElement('h2');bankLedgerTitle.textContent='Bank Account Ledgers';bankLedgerPanel.append(bankLedgerTitle);for(let a of state.bankAccounts){let row=document.createElement('p');row.textContent=a.name+' · Bank Account · Current Balance '+money(balanceOf(a.id));bankLedgerPanel.append(row)}root.append(bankLedgerPanel)}function bankPage(root){root.innerHTML='<h1>Bank Accounts</h1><p>Current book balances and recent transactions.</p><button class="btn primary" id="add-bank">＋ Add Bank Account</button><div class="cards" id="bank-cards"></div><div class="grid" id="bank-list"></div>';root.querySelector('#add-bank').onclick=()=>openBankForm();root.querySelector('#bank-cards').innerHTML=metric('Tracked Accounts',state.bankAccounts.length,'Bank And Cash Accounts','▣')+metric('Combined Book Balance',money(state.bankAccounts.reduce((n,a)=>n+balanceOf(a.id),0)),'Opening Balances Plus Transactions','₹');let list=root.querySelector('#bank-list');for(let a of state.bankAccounts){let panel=document.createElement('section');panel.className='panel';let h=document.createElement('h2');h.textContent=a.name;let b=document.createElement('b');b.textContent=money(balanceOf(a.id));let add=document.createElement('button');add.className='btn';add.textContent='＋ Entry';add.onclick=()=>openLedgerForm('',a.id);let transfer=document.createElement('button');transfer.className='btn';transfer.textContent='⇄ Transfer Funds';transfer.onclick=()=>openBankTransfer(a.id);let edit=document.createElement('button');edit.className='btn';edit.textContent='Edit';edit.onclick=()=>openBankForm(a.id);panel.append(h,document.createTextNode(a.bankName||'Bank'),document.createElement('br'),document.createTextNode('Current Book Balance: '),b,document.createElement('br'),add,transfer,edit);for(let x of accountStatementRows(a.id)){let row=document.createElement('p');row.textContent=x.date+' · '+x.statementDescription+' · '+(x.statementType==='credit'?'+':'−')+money(x.amount)+' · Balance '+money(x.runningBalance);panel.append(row)}list.append(panel)}if(!state.bankAccounts.length)list.textContent='Add a bank or cash account to start tracking balances.'}function ledgerField(label,name,type,value,required){let w=document.createElement('div');w.className='field';let l=document.createElement('label');l.textContent=label;let i=document.createElement('input');i.name=name;i.type=type||'text';i.value=value||'';if(required)i.required=true;w.append(l,i);return w}
